import { render } from '@testing-library/react';
import { SplashScreen } from './splash-screen';

test('confirms __dismissHardSkeleton is invoked before splash animation is rendered in DOM', () => {
  let dismissedBeforeSplashInDOM = false;
  (window as any).__dismissHardSkeleton = jest.fn(() => {
    if (!document.querySelector('[data-testid="tabiji-splash-animation"]')) {
      dismissedBeforeSplashInDOM = true;
    }
  });

  Object.defineProperty(window, 'matchMedia', {
    writable: true,
    value: jest.fn().mockImplementation((query: string) => ({
      matches: query === '(display-mode: standalone)',
    })),
  });

  render(<SplashScreen />);

  expect((window as any).__dismissHardSkeleton).toHaveBeenCalled();
  expect(dismissedBeforeSplashInDOM).toBe(true);
});
